U = {'aziz': 'user', 'dilnoza': 'user', 'admin': 'admin'}
D = {1: {'владелец': 'aziz'}, 2: {'владелец': 'dilnoza'}}
c = {'doc': 1, 'автор': 'aziz', 'текст': '<script>alert(1)</script>'}
code, html = render(c, 'aziz', U, D)
assert code == 200, 'Владелец видит свой документ'
assert '<script>' not in html, 'Скрипт обязан быть экранирован'
assert html == '<p><b>aziz</b>: &lt;script&gt;alert(1)&lt;/script&gt;</p>', 'Разметка своя, содержимое экранировано'
assert render(c, 'dilnoza', U, D) == (403, ''), 'Чужой документ читать нельзя'
assert render(c, 'admin', U, D)[0] == 200, 'Админ читает любой документ'
assert render({'doc': 99, 'автор': 'a', 'текст': 'b'}, 'admin', U, D) == (403, ''), 'Документа нет'
evil = {'doc': 1, 'автор': '<b>злой</b>', 'текст': 'привет'}
assert render(evil, 'aziz', U, D)[1] == '<p><b>&lt;b&gt;злой&lt;/b&gt;</b>: привет</p>', 'Имя автора тоже экранируется'
